package behavior.alignment.repository;import behavior.alignment.profile.*;import java.util.*;public final class InMemoryStructuralAlignmentRepository implements StructuralAlignmentRepository{private final Map<StructuralAlignmentId,StructuralAlignment> data=new LinkedHashMap<>();public synchronized void replaceAll(Collection<StructuralAlignment> values){data.clear();for(StructuralAlignment v:values)if(data.put(v.id(),v)!=null)throw new IllegalArgumentException("duplicate alignment id");}public synchronized Optional<StructuralAlignment> findById(StructuralAlignmentId id){return Optional.ofNullable(data.get(Objects.requireNonNull(id)));}public synchronized List<StructuralAlignment> findAll(){return List.copyOf(data.values());}public synchronized long count(){return data.size();}}
